     2	// eslint-disable-next-line no-control-regex
     3	const DISALLOWED_STATUS_CHARS = /[^\u0009\u0020-\u007E]/g;
     4	
     5	/**
     6	 * Make sure the status message is safe to use in a response.
     7	 *
     8	 * Allowed characters: horizontal tabs, spaces or visible ascii characters: https://www.rfc-editor.org/rfc/rfc7230#section-3.1.2
     9	 */
    10	export function sanitizeStatusMessage(statusMessage = ""): string {
    11	  return statusMessage.replace(DISALLOWED_STATUS_CHARS, "");
    12	}
    13	
    14	/**
    15	 * Make sure the status code is a valid HTTP status code.
    16	 */
    17	export function sanitizeStatusCode(statusCode?: string | number, defaultStatusCode = 200): number {
    18	  if (!statusCode) {
    19	    return defaultStatusCode;
    20	  }
    21	  if (typeof statusCode === "string") {
    22	    statusCode = +statusCode;
    23	  }
    24	  // `Number.isInteger` rejects everything a bare range check would let through: `NaN` (from
    25	  // `+statusCode` on a non-numeric string), floats, and non-numeric values such as objects or
    26	  // arrays, whose comparisons are all `false`. Without it an invalid code leaks through and
    27	  // breaks `Response`.
    28	  if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
    29	    return defaultStatusCode;
    30	  }
    31	  return statusCode;
    32	}
