    16	 */
    17	export function sanitizeStatusCode(statusCode?: string | number, defaultStatusCode = 200): number {
    18	  if (!statusCode) {
    19	    return defaultStatusCode;
    20	  }
    21	  if (typeof statusCode === "string") {
    22	    statusCode = +statusCode;
    23	  }
    24	  // `Number.isInteger` rejects everything a bare range check would let through: `NaN` (from
    25	  // `+statusCode` on a non-numeric string), floats, and non-numeric values such as objects or
    26	  // arrays, whose comparisons are all `false`. Without it an invalid code leaks through and
    27	  // breaks `Response`.
    28	  if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
